generata:
GET COLLECTION tombe;
EXPAND UNPACK TRUE ARRAY .righe TO .elemento;
SAVE AS chaintemp1@ft_it_079;
GET COLLECTION chaintemp1@ft_it_079;
JOIN OF COLLECTIONS chaintemp1@ft_it_079 AS a, defunti@ft_it_079 AS b CASE WHERE .a.elemento.id_defunti = .b._id;

GET COLLECTION tombe; FILTER CASE WHERE .settore != 'C' SAVE AS sub1@ft_it_079;
GET COLLECTION tombe; FILTER CASE WHERE .occupata = TRUE SAVE AS sub2@ft_it_079;
MERGE COLLECTIONS sub1@ft_it_079, sub2@ft_it_079;
